     6→AJumpMapMovingPlatformActor::AJumpMapMovingPlatformActor()
     7→{
     8→	JumpMapObjectId = TEXT("MovingPlatform");
     9→	PrimaryActorTick.bCanEverTick = true;
    10→}
    11→
    12→void AJumpMapMovingPlatformActor::GetSerializableProperties(TMap<FString, FString>& OutProperties) const
    13→{
    14→	OutProperties.Add(TEXT("MoveOffset"), FString::Printf(TEXT("%.2f;%.2f;%.2f"), MoveOffset.X, MoveOffset.Y, MoveOffset.Z));
    15→	OutProperties.Add(TEXT("MoveSpeed"), FString::SanitizeFloat(MoveSpeed));
    16→	OutProperties.Add(TEXT("PauseTime"), FString::SanitizeFloat(PauseTime));
    17→}
    18→
    19→void AJumpMapMovingPlatformActor::ApplySerializedProperties(const TMap<FString, FString>& Properties)
    20→{
    21→	if (const FString* Value = Properties.Find(TEXT("MoveOffset")))
    22→	{
    23→		TArray<FString> Components;
    24→		Value->ParseIntoArray(Components, TEXT(";"), true);
    25→		if (Components.Num() >= 3)
    26→		{
    27→			MoveOffset = FVector(FCString::Atof(*Components[0]), FCString::Atof(*Components[1]), FCString::Atof(*Components[2]));
    28→		}
    29→	}
    30→	if (const FString* Value = Properties.Find(TEXT("MoveSpeed")))
    31→	{
    32→		MoveSpeed = FCString::Atof(**Value);
    33→	}
    34→	if (const FString* Value = Properties.Find(TEXT("PauseTime")))
    35→	{
    36→		PauseTime = FCString::Atof(**Value);
    37→	}
    38→}
    39→
    40→void AJumpMapMovingPlatformActor::BeginPlay()
    41→{
    42→	Super::BeginPlay();
    43→
    44→	OriginalLocation = GetActorLocation();
    45→	TargetLocation = OriginalLocation + MoveOffset;
    46→}
    47→
    48→void AJumpMapMovingPlatformActor::Tick(float DeltaTime)
    49→{
    50→	Super::Tick(DeltaTime);
    51→
    52→	// 정지 상태 처리
    53→	if (bIsPaused)
    54→	{
    55→		PauseTimer -= DeltaTime;
    56→		if (PauseTimer <= 0.f)
    57→		{
    58→			bIsPaused = false;
    59→			bMovingToTarget = !bMovingToTarget;
    60→		}
    61→		return;
    62→	}
    63→
    64→	const FVector CurrentLocation = GetActorLocation();
    65→	const FVector& Destination = bMovingToTarget ? TargetLocation : OriginalLocation;
    66→
    67→	const FVector NewLocation = FMath::VInterpConstantTo(CurrentLocation, Destination, DeltaTime, MoveSpeed);
    68→	SetActorLocation(NewLocation);
    69→
    70→	// 도착 체크
    71→	if (FVector::DistSquared(NewLocation, Destination) < 1.f)
    72→	{
    73→		SetActorLocation(Destination);
    74→		bIsPaused = true;
    75→		PauseTimer = PauseTime;
    76→	}
    77→}
