    18→/**
    19→ * JumpMap 미니게임 규칙
    20→ * - 장애물 코스를 통과하여 결승점에 도달하는 레이스
    21→ * - 사망 시 체크포인트에서 리스폰
    22→ * - 시간 제한 + 완주 순서 기반 승리
    23→ * - 배치 에디터 레이아웃 기반 맵 구성
    24→ */
    25→UCLASS(Blueprintable)
    26→class WJWORLD_API UWjWorldGameRuleJumpMap : public UWjWorldGameRuleBase
    27→{
    28→	GENERATED_BODY()
    29→
    30→public:
    31→	virtual void Initialize(AWjWorldGameModePlay* InGameMode) override;
    32→	virtual void OnGameReady() override;
    33→	virtual void OnGameStart() override;
    34→	virtual void OnGameEnd() override;
    35→	virtual void OnPlayerJoined(AWjWorldPlayerStatePlay* Player) override;
    36→	virtual void OnPlayerLeft(AWjWorldPlayerStatePlay* Player) override;
    37→
    38→	virtual bool CheckWinCondition() const override;
    39→	virtual AWjWorldPlayerStatePlay* GetWinner() const override;
    40→
    41→	/** 플레이어 사망 → 체크포인트에서 리스폰 */
    42→	void OnPlayerDied(AWjWorldCharacterPlay* Character);
    43→
    44→	/** 플레이어 완주 */
    45→	void OnPlayerFinished(AWjWorldCharacterPlay* Character);
    46→
    47→protected:
    48→	virtual void TickGameRule(float DeltaTime) override;
    49→
    50→private:
    51→	void LoadLayoutAndSpawnActors();
    52→	void SpawnActorsFromLayout(const FJumpMapLayout& Layout);
    53→	void RespawnPlayerAtCheckpoint(AWjWorldCharacterPlay* Character, int32 CheckpointIndex);
    54→	void UpdateGameData();
    55→
    56→protected:
    57→	/** 제한 시간 (초) */
    58→	UPROPERTY(EditDefaultsOnly, Category = "GameRule")
    59→	float TimeLimit = 120.f;
    60→
    61→	/** 리스폰 대기 시간 (초) */
    62→	UPROPERTY(EditDefaultsOnly, Category = "GameRule")
    63→	float RespawnDelay = 1.f;
    64→
    65→	/** 낙하 판정 Z 좌표 (이 미만이면 사망) */
    66→	UPROPERTY(EditDefaultsOnly, Category = "GameRule")
    67→	float FallThresholdZ = -500.f;
    68→
    69→	/** ObjectId → 게임플레이 액터 클래스 매핑 (BP에서 설정) */
    70→	UPROPERTY(EditDefaultsOnly, Category = "GameRule|Layout")
    71→	TMap<FName, TSubclassOf<AActor>> ObjectIdToActorClassMap;
    72→
    73→private:
    74→	UPROPERTY()
    75→	TArray<TWeakObjectPtr<AActor>> SpawnedGameplayActors;
    76→
    77→	UPROPERTY()
    78→	TArray<TWeakObjectPtr<AWjWorldPlayerStatePlay>> AllPlayers;
    79→
    80→	UPROPERTY()
    81→	TWeakObjectPtr<AWjWorldPlayerStatePlay> WinnerPlayer;
    82→
    83→	FVector StartLocation = FVector::ZeroVector;
    84→	TArray<FVector> CheckpointLocations;
    85→
    86→	float ElapsedTime = 0.f;
    87→	int32 TotalPlayerCount = 0;
    88→	int32 FinishedPlayerCount = 0;
    89→	bool bIsGameStarted = false;
    90→	bool bGameOverConditionMet = false;
    91→};
