    24→void UWjWorldGameRuleJumpMap::Initialize(AWjWorldGameModePlay* InGameMode)
    25→{
    26→	Super::Initialize(InGameMode);
    27→
    28→	GameDataComponentClass = UJumpMapGameDataComponent::StaticClass();
    29→	PlayerDataComponentClass = UJumpMapPlayerDataComponent::StaticClass();
    30→
    31→	// MapOption에서 레이아웃 이름 파싱
    32→	if (InGameMode)
    33→	{
    34→		const FString& MapOpt = InGameMode->GetMapOption();
    35→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: MapOption = '%s'"), *MapOpt);
    36→	}
    37→
    38→	// 레이아웃 로드 및 게임플레이 액터 스폰
    39→	LoadLayoutAndSpawnActors();
    40→
    41→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Initialized (TimeLimit=%.1f, FallThreshold=%.1f)"),
    42→		TimeLimit, FallThresholdZ);
    43→}
    44→
    45→void UWjWorldGameRuleJumpMap::LoadLayoutAndSpawnActors()
    46→{
    47→	UWorld* World = GetWorld();
    48→	if (!World) return;
    49→
    50→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    51→	if (!DevSettings) return;
    52→
    53→	// MapOption에서 레이아웃 이름 가져오기
    54→	FString MapOpt;
    55→	AWjWorldGameModePlay* GameModePlay = GetGameModePlay();
    56→	if (GameModePlay)
    57→	{
    58→		MapOpt = GameModePlay->GetMapOption();
    59→	}
    60→
    61→	// DataAsset에서 레이아웃 로드
    62→	bool bLayoutLoaded = false;
    63→	if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
    64→	{
    65→		UJumpMapLayoutDataAsset* LayoutAsset = DevSettings->JumpMapLayoutDataAsset.LoadSynchronous();
    66→		if (LayoutAsset)
    67→		{
    68→			FString LayoutName;
    69→
    70→			if (MapOpt.IsEmpty() || MapOpt.Equals(TEXT("Default"), ESearchCase::IgnoreCase))
    71→			{
    72→				// Default: BuiltInLayouts 첫 번째 레이아웃
    73→				if (LayoutAsset->BuiltInLayouts.Num() > 0)
    74→				{
    75→					LayoutName = LayoutAsset->BuiltInLayouts[0].LayoutName;
    76→				}
    77→			}
    78→			else if (MapOpt.Equals(TEXT("Random"), ESearchCase::IgnoreCase))
    79→			{
    80→				LayoutName = LayoutAsset->GetRandomLayoutName();
    81→			}
    82→			else
    83→			{
    84→				// 직접 지정된 레이아웃 이름 (유저 레이아웃 포함)
    85→				LayoutName = MapOpt;
    86→			}
    87→
    88→			if (!LayoutName.IsEmpty())
    89→			{
    90→				const FJumpMapLayout* Layout = LayoutAsset->GetLayoutByNameIncludingUser(LayoutName);
    91→				if (Layout)
    92→				{
    93→					SpawnActorsFromLayout(*Layout);
    94→					bLayoutLoaded = true;
    95→					UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Loaded layout '%s' (%d objects)"),
    96→						*LayoutName, Layout->Objects.Num());
    97→				}
    98→				else
    99→				{
   100→					UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: Layout '%s' not found"), *LayoutName);
   101→				}
   102→			}
   103→		}
   104→	}
   105→
   106→	if (!bLayoutLoaded)
   107→	{
   108→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Using map-placed actors (no layout loaded)"));
   109→	}
   110→
   111→	// 체크포인트/엔드 액터 수집 (CSV 로딩 후에도 실행하여 CheckpointLocations 갱신)
   112→	CheckpointLocations.Empty();
   113→	for (TActorIterator<AJumpMapCheckpointActor> It(World); It; ++It)
   114→	{
   115→		AJumpMapCheckpointActor* Checkpoint = *It;
   116→		if (Checkpoint)
   117→		{
   118→			int32 Order = Checkpoint->CheckpointOrder;
   119→			if (CheckpointLocations.Num() <= Order)
   120→			{
   121→				CheckpointLocations.SetNum(Order + 1);
   122→			}
   123→			CheckpointLocations[Order] = Checkpoint->GetActorLocation();
   124→
   125→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Checkpoint %d at %s"),
   126→				Order, *Checkpoint->GetActorLocation().ToString());
   127→		}
   128→	}
   129→
   130→	for (TActorIterator<AJumpMapEndActor> It(World); It; ++It)
   131→	{
   132→		AJumpMapEndActor* EndActor = *It;
   133→		if (EndActor)
   134→		{
   135→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: End actor at %s"),
   136→				*EndActor->GetActorLocation().ToString());
   137→		}
   138→	}
   139→
   140→	// 플레이어 스타트에서 시작 위치 가져오기
   141→	AActor* PlayerStart = UGameplayStatics::GetActorOfClass(World, APlayerStart::StaticClass());
   142→	if (PlayerStart)
   143→	{
   144→		StartLocation = PlayerStart->GetActorLocation();
   145→	}
   146→
   147→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Layout loaded - Start: %s, Checkpoints: %d"),
   148→		*StartLocation.ToString(), CheckpointLocations.Num());
   149→}
   150→
   151→void UWjWorldGameRuleJumpMap::SpawnActorsFromLayout(const FJumpMapLayout& Layout)
   152→{
   153→	UWorld* World = GetWorld();
   154→	if (!World) return;
   155→
   156→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   157→
   158→	for (const FJumpMapLayoutEntry& Entry : Layout.Objects)
   159→	{
   160→		// BP 프로퍼티에서 먼저 조회
   161→		TSubclassOf<AActor> ActorClass = nullptr;
   162→		if (const TSubclassOf<AActor>* Found = ObjectIdToActorClassMap.Find(Entry.ObjectId))
   163→		{
   164→			ActorClass = *Found;
   165→		}
   166→		else if (DevSettings)
   167→		{
   168→			// DeveloperSettings 폴백
   169→			if (const TSoftClassPtr<AJumpMapActorBase>* SoftFound =
   170→				DevSettings->JumpMapObjectIdToClassMap.Find(Entry.ObjectId))
   171→			{
   172→				ActorClass = SoftFound->LoadSynchronous();
   173→			}
   174→		}
   175→
   176→		if (!ActorClass)
   177→		{
   178→			UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: No class for ObjectId '%s'"), *Entry.ObjectId.ToString());
   179→			continue;
   180→		}
   181→
   182→		FActorSpawnParameters SpawnParams;
   183→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   184→
   185→		AActor* NewActor = World->SpawnActor<AActor>(ActorClass, Entry.Transform, SpawnParams);
   186→		if (NewActor)
   187→		{
   188→			// JumpMapActorBase인 경우 CustomProperties 적용
   189→			AJumpMapActorBase* JumpMapActor = Cast<AJumpMapActorBase>(NewActor);
   190→			if (JumpMapActor)
   191→			{
   192→				JumpMapActor->InitializeFromLayoutEntry(Entry.Transform);
   193→				JumpMapActor->ApplySerializedProperties(Entry.CustomProperties);
   194→			}
   195→
   196→			SpawnedGameplayActors.Add(NewActor);
   197→		}
   198→	}
   199→
   200→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Spawned %d actors from layout"), SpawnedGameplayActors.Num());
   201→}
   202→
   203→void UWjWorldGameRuleJumpMap::OnGameReady()
   204→{
   205→	if (!HasAuthority()) return;
   206→
   207→	Super::OnGameReady();
   208→
   209→	// GameData에 초기 정보 설정
   210→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   211→	if (GameState)
   212→	{
   213→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   214→		if (GameData)
   215→		{
   216→			GameData->SetTimeLimit(TimeLimit);
   217→			GameData->SetTotalPlayerCount(TotalPlayerCount);
   218→		}
   219→	}
   220→
   221→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Game Ready - Players: %d, Checkpoints: %d"),
   222→		TotalPlayerCount, CheckpointLocations.Num());
   223→}
   224→
   225→void UWjWorldGameRuleJumpMap::OnGameStart()
   226→{
   227→	if (!HasAuthority()) return;
   228→
   229→	Super::OnGameStart();
   230→
   231→	bIsGameStarted = true;
   232→	ElapsedTime = 0.f;
   233→
   234→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Game Started - Players: %d, TimeLimit: %.1f"),
   235→		TotalPlayerCount, TimeLimit);
   236→
   237→	// 엣지 케이스: 플레이어 없음
   238→	if (TotalPlayerCount <= 0)
   239→	{
   240→		UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: No players, ending game"));
   241→		bGameOverConditionMet = true;
   242→		WinnerPlayer = nullptr;
   243→		OnGameEnd();
   244→		return;
   245→	}
   246→}
   247→
   248→void UWjWorldGameRuleJumpMap::OnGameEnd()
   249→{
   250→	if (!HasAuthority()) return;
   251→
   252→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   253→	if (GameState)
   254→	{
   255→		// 승자 결정: 가장 빠른 완주 시간
   256→		if (!WinnerPlayer.IsValid())
   257→		{
   258→			float BestTime = MAX_FLT;
   259→			for (const auto& WeakPS : AllPlayers)
   260→			{
   261→				if (!WeakPS.IsValid()) continue;
   262→				AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   263→				UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   264→				if (PlayerData && PlayerData->HasFinished() && PlayerData->GetFinishTime() < BestTime)
   265→				{
   266→					BestTime = PlayerData->GetFinishTime();
   267→					WinnerPlayer = PS;
   268→				}
   269→			}
   270→		}
   271→
   272→		if (WinnerPlayer.IsValid())
   273→		{
   274→			GameState->SetGameResult(WinnerPlayer->GetPlayerName(), true);
   275→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Winner: %s"), *WinnerPlayer->GetPlayerName());
   276→		}
   277→		else
   278→		{
   279→			GameState->SetGameResult(TEXT(""), false);
   280→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: No winner (time expired)"));
   281→		}
   282→	}
   283→
   284→	// 스폰된 게임플레이 액터 정리
   285→	for (const auto& WeakActor : SpawnedGameplayActors)
   286→	{
   287→		if (WeakActor.IsValid())
   288→		{
   289→			WeakActor->Destroy();
   290→		}
   291→	}
   292→	SpawnedGameplayActors.Empty();
   293→
   294→	Super::OnGameEnd();
   295→}
   296→
   297→void UWjWorldGameRuleJumpMap::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   298→{
   299→	Super::OnPlayerJoined(Player);
   300→
   301→	if (!HasAuthority() || !Player) return;
   302→
   303→	AllPlayers.Add(Player);
   304→	TotalPlayerCount++;
   305→
   306→	UpdateGameData();
   307→
   308→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Joined - %s, Total: %d"),
   309→		*Player->GetPlayerName(), TotalPlayerCount);
   310→}
   311→
   312→void UWjWorldGameRuleJumpMap::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   313→{
   314→	Super::OnPlayerLeft(Player);
   315→
   316→	if (!HasAuthority() || !Player) return;
   317→
   318→	AllPlayers.Remove(Player);
   319→	TotalPlayerCount--;
   320→
   321→	UpdateGameData();
   322→
   323→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Left - %s, Total: %d"),
   324→		*Player->GetPlayerName(), TotalPlayerCount);
   325→
   326→	// 모든 플레이어 이탈
   327→	if (TotalPlayerCount <= 0)
   328→	{
   329→		bGameOverConditionMet = true;
   330→		WinnerPlayer = nullptr;
   331→		OnGameEnd();
   332→		return;
   333→	}
   334→
   335→	// 남은 플레이어가 모두 완주했는지 체크
   336→	int32 ActivePlayers = 0;
   337→	for (const auto& WeakPS : AllPlayers)
   338→	{
   339→		if (!WeakPS.IsValid()) continue;
   340→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   341→		if (!PlayerData || !PlayerData->HasFinished())
   342→		{
   343→			ActivePlayers++;
   344→		}
   345→	}
   346→
   347→	if (ActivePlayers == 0 && FinishedPlayerCount > 0)
   348→	{
   349→		bGameOverConditionMet = true;
   350→		OnGameEnd();
   351→	}
   352→}
