   377→void UWjWorldGameRuleJumpMap::RespawnPlayerAtCheckpoint(AWjWorldCharacterPlay* Character, int32 CheckpointIndex)
   378→{
   379→	if (!Character) return;
   380→
   381→	FVector RespawnLocation;
   382→	if (CheckpointIndex >= 0 && CheckpointIndex < CheckpointLocations.Num())
   383→	{
   384→		RespawnLocation = CheckpointLocations[CheckpointIndex];
   385→	}
   386→	else
   387→	{
   388→		RespawnLocation = StartLocation;
   389→	}
   390→
   391→	// 약간 위에 스폰 (바닥 충돌 방지)
   392→	RespawnLocation.Z += 100.f;
   393→
   394→	Character->SetActorLocation(RespawnLocation);
   395→
   396→	// 속도 초기화
   397→	if (UCharacterMovementComponent* MC = Character->GetCharacterMovement())
   398→	{
   399→		MC->StopMovementImmediately();
   400→	}
   401→
   402→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Respawned at checkpoint %d (%s)"),
   403→		CheckpointIndex, *RespawnLocation.ToString());
   404→}
