   474→void UWjWorldGameRuleJumpMap::TickGameRule(float DeltaTime)
   475→{
   476→	if (!HasAuthority()) return;
   477→	if (!bIsGameStarted || bGameOverConditionMet) return;
   478→
   479→	// 경과 시간 업데이트
   480→	ElapsedTime += DeltaTime;
   481→
   482→	// GameData 업데이트
   483→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   484→	if (GameState)
   485→	{
   486→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   487→		if (GameData)
   488→		{
   489→			GameData->SetElapsedTime(ElapsedTime);
   490→		}
   491→	}
   492→
   493→	// 낙하 플레이어 체크
   494→	for (const auto& WeakPS : AllPlayers)
   495→	{
   496→		if (!WeakPS.IsValid()) continue;
   497→
   498→		APawn* Pawn = WeakPS->GetPawn();
   499→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   500→		if (!Character) continue;
   501→
   502→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   503→		if (PlayerData && PlayerData->HasFinished()) continue;
   504→
   505→		if (Character->GetActorLocation().Z < FallThresholdZ)
   506→		{
   507→			OnPlayerDied(Character);
   508→		}
   509→	}
   510→
   511→	// 시간 제한 체크
   512→	if (TimeLimit > 0.f && ElapsedTime >= TimeLimit)
   513→	{
   514→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Time limit reached (%.1f)"), TimeLimit);
   515→		bGameOverConditionMet = true;
   516→		OnGameEnd();
   517→	}
   518→}
