   520→void UWjWorldGameRuleJumpMap::UpdateGameData()
   521→{
   522→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   523→	if (!GameState) return;
   524→
   525→	UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   526→	if (!GameData) return;
   527→
   528→	GameData->SetTotalPlayerCount(TotalPlayerCount);
   529→	GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   530→}
