    75→void AJumpMapRotatingObstacleActor::OnHitOverlap(UPrimitiveComponent* OverlappedComp, AActor* OtherActor,
    76→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
    77→{
    78→	if (!HasAuthority()) return;
    79→
    80→	AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(OtherActor);
    81→	if (!Character || Character->IsEliminated()) return;
    82→
    83→	if (bKillOnHit)
    84→	{
    85→		UWorld* World = GetWorld();
    86→		if (World)
    87→		{
    88→			AWjWorldGameModePlay* GameMode = Cast<AWjWorldGameModePlay>(World->GetAuthGameMode());
    89→			if (GameMode)
    90→			{
    91→				UWjWorldGameRuleJumpMap* GameRule = GameMode->GetCurrentGameRule<UWjWorldGameRuleJumpMap>();
    92→				if (GameRule)
    93→				{
    94→					GameRule->OnPlayerDied(Character);
    95→				}
    96→			}
    97→		}
    98→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapRotatingObstacle: Killed player [%s]"), *Character->GetName());
    99→	}
   100→	else
   101→	{
   102→		// 넉백 방향: 장애물 중심에서 캐릭터 방향
   103→		FVector KnockbackDir = (Character->GetActorLocation() - GetActorLocation()).GetSafeNormal();
   104→		KnockbackDir.Z = FMath::Max(KnockbackDir.Z, 0.3f); // 약간의 상향 넉백
   105→		KnockbackDir.Normalize();
   106→
   107→		Character->LaunchCharacter(KnockbackDir * KnockbackForce, true, true);
   108→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapRotatingObstacle: Knocked back player [%s]"), *Character->GetName());
   109→	}
   110→}
