    66→void ACharacterPreviewActor::SetupFromPawn(APawn* SourcePawn)
    67→{
    68→	if (!SourcePawn)
    69→	{
    70→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: SetupFromPawn called with null pawn"));
    71→		return;
    72→	}
    73→
    74→	// ACharacter에서 메시 컴포넌트 가져오기
    75→	ACharacter* SourceCharacter = Cast<ACharacter>(SourcePawn);
    76→	if (!SourceCharacter)
    77→	{
    78→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: SourcePawn is not a Character"));
    79→		return;
    80→	}
    81→
    82→	USkeletalMeshComponent* SourceMesh = SourceCharacter->GetMesh();
    83→	if (!SourceMesh)
    84→	{
    85→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: Source character has no mesh"));
    86→		return;
    87→	}
    88→
    89→	// SkeletalMesh 복사
    90→	USkeletalMesh* SkelMesh = SourceMesh->GetSkeletalMeshAsset();
    91→	if (SkelMesh)
    92→	{
    93→		PreviewMeshComponent->SetSkeletalMesh(SkelMesh);
    94→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Copied SkeletalMesh %s"), *SkelMesh->GetName());
    95→	}
    96→
    97→	// 소스 메시의 회전값 복사 (ACharacter의 Yaw=-90° 보정 포함)
    98→	PreviewMeshComponent->SetRelativeRotation(SourceMesh->GetRelativeRotation());
    99→
   100→	// AnimBlueprint 복사
   101→	UClass* AnimClass = SourceMesh->GetAnimClass();
   102→	if (AnimClass)
   103→	{
   104→		PreviewMeshComponent->SetAnimInstanceClass(AnimClass);
   105→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Copied AnimBlueprint %s"), *AnimClass->GetName());
   106→	}
   107→
   108→	// 애니메이션 재생을 위해 가시성 및 틱 활성화
   109→	PreviewMeshComponent->SetVisibility(true);
   110→	PreviewMeshComponent->VisibilityBasedAnimTickOption = EVisibilityBasedAnimTickOption::AlwaysTickPoseAndRefreshBones;
   111→
   112→	// 메시 설정 완료 후 실시간 캡처 활성화 (Idle 모션 반영)
   113→	SceneCaptureComponent->bCaptureEveryFrame = true;
   114→
   115→	RefreshCapture();
   116→}
