   122→
   123→void ACharacterPreviewActor::SetupPreview(const FCosmeticLoadout& Loadout)
   124→{
   125→	// 기존 코스메틱 메시 제거
   126→	for (auto& Pair : SlotMeshComponents)
   127→	{
   128→		if (Pair.Value)
   129→		{
   130→			Pair.Value->DestroyComponent();
   131→		}
   132→	}
   133→	SlotMeshComponents.Empty();
   134→	ActiveStreamHandles.Empty();
   135→
   136→	// 카탈로그 가져오기
   137→	UGameInstance* GI = GetGameInstance();
   138→	if (!GI)
   139→	{
   140→		return;
   141→	}
   142→
   143→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   144→	if (!CosmeticSub)
   145→	{
   146→		return;
   147→	}
   148→
   149→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   150→	if (!Catalog)
   151→	{
   152→		RefreshCapture();
   153→		return;
   154→	}
   155→
   156→	// 코스메틱 로드아웃 적용
   157→	for (const FCosmeticSlotEntry& Entry : Loadout.Entries)
   158→	{
   159→		if (Entry.Slot == ECosmeticSlot::None || Entry.ItemId.IsNone())
   160→		{
   161→			continue;
   162→		}
   163→
   164→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(Entry.ItemId);
   165→		if (!ItemDef)
   166→		{
   167→			continue;
   168→		}
   169→
   170→		// StaticMesh 또는 SkeletalMesh 비동기 로드
   171→		FSoftObjectPath MeshPath;
   172→		if (!ItemDef->StaticMesh.IsNull())
   173→		{
   174→			MeshPath = ItemDef->StaticMesh.ToSoftObjectPath();
   175→		}
   176→		else if (!ItemDef->SkeletalMesh.IsNull())
   177→		{
   178→			MeshPath = ItemDef->SkeletalMesh.ToSoftObjectPath();
   179→		}
   180→
   181→		if (!MeshPath.IsNull())
   182→		{
   183→			ECosmeticSlot CapturedSlot = Entry.Slot;
   184→			FName CapturedItemId = Entry.ItemId;
   185→
   186→			TSharedPtr<FStreamableHandle> Handle = StreamableManager.RequestAsyncLoad(
   187→				MeshPath,
   188→				FStreamableDelegate::CreateWeakLambda(this, [this, CapturedSlot, CapturedItemId]()
   189→				{
   190→					OnCosmeticAssetLoaded(CapturedSlot, CapturedItemId);
   191→				})
   192→			);
   193→
   194→			if (Handle.IsValid())
   195→			{
   196→				ActiveStreamHandles.Add(CapturedSlot, Handle);
   197→			}
   198→		}
   199→	}
   200→
   201→	// 코스메틱이 없으면 바로 캡처
   202→	if (Loadout.IsEmpty())
   203→	{
   204→		RefreshCapture();
   205→	}
   206→}
   207→
   208→void ACharacterPreviewActor::OnCosmeticAssetLoaded(ECosmeticSlot Slot, FName ItemId)
   209→{
   210→	UGameInstance* GI = GetGameInstance();
   211→	if (!GI)
   212→	{
   213→		return;
   214→	}
   215→
   216→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   217→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   218→	{
   219→		return;
   220→	}
   221→
   222→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(ItemId);
   223→	if (!ItemDef)
   224→	{
   225→		return;
   226→	}
   227→
   228→	// StaticMesh 우선, 없으면 SkeletalMesh 시도
   229→	UObject* LoadedAsset = nullptr;
   230→	if (!ItemDef->StaticMesh.IsNull())
   231→	{
   232→		LoadedAsset = ItemDef->StaticMesh.ToSoftObjectPath().ResolveObject();
   233→	}
   234→	else if (!ItemDef->SkeletalMesh.IsNull())
   235→	{
   236→		LoadedAsset = ItemDef->SkeletalMesh.ToSoftObjectPath().ResolveObject();
   237→	}
   238→
   239→	// 부착 소켓 결정
   240→	FName SocketName = ItemDef->AttachSocketName;
   241→	if (SocketName.IsNone())
   242→	{
   243→		SocketName = GetDefaultSocketName(ItemDef->Slot);
   244→	}
   245→
   246→	// 메시 컴포넌트 생성 및 부착
   247→	UMeshComponent* NewMeshComp = nullptr;
   248→
   249→	if (UStaticMesh* StaticMesh = Cast<UStaticMesh>(LoadedAsset))
   250→	{
   251→		UStaticMeshComponent* StaticMeshComp = NewObject<UStaticMeshComponent>(this);
   252→		StaticMeshComp->SetCollisionEnabled(ECollisionEnabled::NoCollision);
   253→		StaticMeshComp->SetStaticMesh(StaticMesh);
   254→		NewMeshComp = StaticMeshComp;
   255→	}
   256→	else if (USkeletalMesh* SkeletalMesh = Cast<USkeletalMesh>(LoadedAsset))
   257→	{
   258→		USkeletalMeshComponent* SkelMeshComp = NewObject<USkeletalMeshComponent>(this);
   259→		SkelMeshComp->SetCollisionEnabled(ECollisionEnabled::NoCollision);
   260→		SkelMeshComp->SetSkeletalMesh(SkeletalMesh);
   261→		NewMeshComp = SkelMeshComp;
   262→	}
   263→
   264→	if (NewMeshComp)
   265→	{
   266→		// Socket 부착 또는 단순 부착
   267→		if (!SocketName.IsNone() && PreviewMeshComponent->DoesSocketExist(SocketName))
   268→		{
   269→			NewMeshComp->AttachToComponent(PreviewMeshComponent,
   270→				FAttachmentTransformRules::SnapToTargetNotIncludingScale, SocketName);
   271→		}
   272→		else
   273→		{
   274→			NewMeshComp->SetupAttachment(PreviewMeshComponent);
   275→		}
   276→
   277→		// 오프셋 및 스케일 적용
   278→		NewMeshComp->SetRelativeLocation(ItemDef->AttachLocationOffset);
   279→		NewMeshComp->SetRelativeRotation(ItemDef->AttachRotationOffset);
   280→		NewMeshComp->SetRelativeScale3D(ItemDef->AttachScale);
   281→
   282→		NewMeshComp->RegisterComponent();
   283→
   284→		SlotMeshComponents.Add(Slot, NewMeshComp);
   285→		SceneCaptureComponent->ShowOnlyComponents.Add(NewMeshComp);
   286→
   287→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Loaded cosmetic %s on slot %d (socket: %s)"),
   288→			*ItemId.ToString(), static_cast<int32>(Slot), *SocketName.ToString());
   289→	}
   290→
   291→	// 모든 로드가 완료되었는지 확인
   292→	ActiveStreamHandles.Remove(Slot);
   293→	if (ActiveStreamHandles.Num() == 0)
   294→	{
   295→		RefreshCapture();
   296→	}
   297→}
   298→
   299→FName ACharacterPreviewActor::GetDefaultSocketName(ECosmeticSlot Slot)
   300→{
   301→	switch (Slot)
   302→	{
   303→	case ECosmeticSlot::Head:
   304→		return FName("head");
   305→	case ECosmeticSlot::Back:
   306→		return FName("spine_03");
   307→	case ECosmeticSlot::Effect:
   308→		return FName("root");
   309→	default:
   310→		return NAME_None;
   311→	}
   312→}
   313→
   314→void ACharacterPreviewActor::RefreshCapture()
   315→{
   316→	if (SceneCaptureComponent && RenderTarget)
   317→	{
   318→		SceneCaptureComponent->CaptureScene();
   319→
   320→		UE_LOG(LogWjWorld, Log, TEXT("CharacterPreviewActor: Scene captured"));
   321→	}
   322→}
