    90→void UWjWorldCurrencySubsystem::TriggerMatchReward(bool bIsWinner)
    91→{
    92→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    93→	if (!Settings)
    94→	{
    95→		return;
    96→	}
    97→
    98→	int32 GeneratorDefId = bIsWinner ? Settings->MatchWinRewardDefId : Settings->MatchLossRewardDefId;
    99→
   100→	UE_LOG(LogWjWorldCurrency, Log, TEXT("매치 보상 트리거: %s (GeneratorDefId: %d)"),
   101→		bIsWinner ? TEXT("승리") : TEXT("패배"), GeneratorDefId);
   102→
   103→#if WITH_STEAM
   104→	ISteamInventory* SteamInv = SteamInventory();
   105→	if (SteamInv)
   106→	{
   107→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   108→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   109→
   110→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   111→		{
   112→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam TriggerItemDrop 요청 성공 (DefId: %d)"), GeneratorDefId);
   113→			SteamInv->DestroyResult(ResultHandle);
   114→
   115→			// Steam 서버 반영 대기 후 인벤토리 갱신 (즉시 호출 시 이전 잔액 반환)
   116→			UWorld* World = GetWorld();
   117→			if (World)
   118→			{
   119→				FTimerHandle TimerHandle;
   120→				World->GetTimerManager().SetTimer(TimerHandle, [WeakThis = TWeakObjectPtr<UWjWorldCurrencySubsystem>(this)]()
   121→				{
   122→					if (UWjWorldCurrencySubsystem* Self = WeakThis.Get())
   123→					{
   124→						UWjWorldCosmeticSubsystem* CosmeticSub = Self->GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   125→						if (CosmeticSub)
   126→						{
   127→							CosmeticSub->RequestInventoryRefresh();
   128→						}
   129→					}
   130→				}, 1.5f, false);
   131→			}
   132→		}
   133→		else
   134→		{
   135→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam TriggerItemDrop 실패 (DefId: %d)"), GeneratorDefId);
   136→		}
   137→
   138→		return;
   139→	}
   140→#endif
   141→
   142→	// 비Steam 폴백: 로컬 잔액 직접 증가
   143→	int32 RewardAmount = bIsWinner ? 50 : 10;
   144→	GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   145→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 매치 보상 지급: %d Coin"), RewardAmount);
   146→}
