   148→bool UWjWorldCurrencySubsystem::PurchaseItemWithCurrency(FName CosmeticItemId, ECurrencyType CurrencyType)
   149→{
   150→	if (bExchangePending)
   151→	{
   152→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   153→		return false;
   154→	}
   155→
   156→	if (CosmeticItemId.IsNone())
   157→	{
   158→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 CosmeticItemId"));
   159→		return false;
   160→	}
   161→
   162→	// 카탈로그에서 아이템 정보 조회
   163→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   164→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   165→	{
   166→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("CosmeticSubsystem 또는 카탈로그 없음"));
   167→		return false;
   168→	}
   169→
   170→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(CosmeticItemId);
   171→	if (!ItemDef)
   172→	{
   173→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 아이템 '%s' 찾을 수 없음"), *CosmeticItemId.ToString());
   174→		return false;
   175→	}
   176→
   177→	// 가격 확인
   178→	int32 ItemPrice = (CurrencyType == ECurrencyType::Coin) ? ItemDef->CoinPrice : ItemDef->GemPrice;
   179→	if (ItemPrice <= 0)
   180→	{
   181→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("아이템 '%s'은 %s로 구매할 수 없습니다 (가격: %d)"),
   182→			*CosmeticItemId.ToString(),
   183→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   184→			ItemPrice);
   185→		return false;
   186→	}
   187→
   188→	// 잔액 확인
   189→	int32 CurrentBalance = GetBalance(CurrencyType);
   190→	if (CurrentBalance < ItemPrice)
   191→	{
   192→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("잔액 부족: %s %d < %d"),
   193→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   194→			CurrentBalance, ItemPrice);
   195→		return false;
   196→	}
   197→
   198→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   199→	if (!Settings)
   200→	{
   201→		return false;
   202→	}
   203→
   204→	int32 CurrencyDefId = (CurrencyType == ECurrencyType::Coin) ? Settings->CoinSteamItemDefId : Settings->GemSteamItemDefId;
   205→	int32 CosmeticDefId = ItemDef->SteamItemDefId;
   206→
   207→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 구매 요청: %s (%d %s → CosmeticDefId %d)"),
   208→		*CosmeticItemId.ToString(), ItemPrice,
   209→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   210→		CosmeticDefId);
   211→
   212→#if WITH_STEAM
   213→	ISteamInventory* SteamInv = SteamInventory();
   214→	if (SteamInv && CosmeticDefId > 0)
   215→	{
   216→		// 캐시된 재화 인스턴스 ID 조회
   217→		SteamItemInstanceID_t CurrencyInstanceId = (CurrencyType == ECurrencyType::Coin)
   218→			? CachedCoinInstanceId
   219→			: CachedGemInstanceId;
   220→
   221→		if (CurrencyInstanceId == k_SteamItemInstanceIDInvalid)
   222→		{
   223→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("재화 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   224→			return false;
   225→		}
   226→
   227→		// 기존 핸들 정리
   228→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   229→		{
   230→			SteamInv->DestroyResult(ExchangeResultHandle);
   231→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   232→		}
   233→
   234→		// ExchangeItems: 재화 소비 → 코스메틱 아이템 획득
   235→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(CosmeticDefId);
   236→		uint32 OutputQuantity = 1;
   237→
   238→		uint32 InputQuantity = static_cast<uint32>(ItemPrice);
   239→
   240→		bool bExchangeResult = SteamInv->ExchangeItems(
   241→			&ExchangeResultHandle,
   242→			&OutputItemDef, &OutputQuantity, 1,       // 출력: 코스메틱 아이템 1개
   243→			&CurrencyInstanceId, &InputQuantity, 1     // 입력: 재화 인스턴스 × 가격
   244→		);
   245→
   246→		if (bExchangeResult)
   247→		{
   248→			bExchangePending = true;
   249→			bPendingIsPlacement = false;
   250→			PendingExchangeItemId = CosmeticItemId;
   251→			StartExchangePolling();
   252→
   253→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공: %s (CurrencyInstanceId=%llu, Price=%d)"),
   254→				*CosmeticItemId.ToString(), CurrencyInstanceId, ItemPrice);
   255→			return true;
   256→		}
   257→		else
   258→		{
   259→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패: %s"), *CosmeticItemId.ToString());
   260→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   261→			return false;
   262→		}
   263→	}
   264→#endif
   265→
   266→	// 비Steam 폴백: 로컬 잔액 차감 + 아이템 부여
   267→	SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   268→	CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   269→
   270→	OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   271→
   272→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 구매 완료: %s (%d %s 차감)"),
   273→		*CosmeticItemId.ToString(), ItemPrice,
   274→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"));
   275→
   276→	return true;
   277→}
