   279→bool UWjWorldCurrencySubsystem::PurchasePlacementObject(FName ObjectId)
   280→{
   281→	if (bExchangePending)
   282→	{
   283→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   284→		return false;
   285→	}
   286→
   287→	if (ObjectId.IsNone())
   288→	{
   289→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 ObjectId"));
   290→		return false;
   291→	}
   292→
   293→	// DeveloperSettings에서 LobbyPlaceableCatalog 로드
   294→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   295→	if (!Settings)
   296→	{
   297→		return false;
   298→	}
   299→
   300→	UWjWorldPlaceableObjectDataAsset* PlacementCatalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   301→	if (!PlacementCatalog)
   302→	{
   303→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("LobbyPlaceableCatalog 없음"));
   304→		return false;
   305→	}
   306→
   307→	const FPlaceableObjectDefinition* Def = PlacementCatalog->FindByObjectId(ObjectId);
   308→	if (!Def)
   309→	{
   310→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 오브젝트 '%s' 찾을 수 없음"), *ObjectId.ToString());
   311→		return false;
   312→	}
   313→
   314→	if (Def->CoinPrice <= 0)
   315→	{
   316→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("오브젝트 '%s'은 무료입니다 (구매 불필요)"), *ObjectId.ToString());
   317→		return false;
   318→	}
   319→
   320→	if (Def->SteamItemDefId <= 0)
   321→	{
   322→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("오브젝트 '%s'에 SteamItemDefId가 설정되지 않음"), *ObjectId.ToString());
   323→		return false;
   324→	}
   325→
   326→	// 잔액 확인
   327→	int32 CurrentBalance = GetBalance(ECurrencyType::Coin);
   328→	if (CurrentBalance < Def->CoinPrice)
   329→	{
   330→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Coin 잔액 부족: %d < %d"), CurrentBalance, Def->CoinPrice);
   331→		return false;
   332→	}
   333→
   334→	UE_LOG(LogWjWorldCurrency, Log, TEXT("배치 오브젝트 구매 요청: %s (%d Coin → DefId %d)"),
   335→		*ObjectId.ToString(), Def->CoinPrice, Def->SteamItemDefId);
   336→
   337→#if WITH_STEAM
   338→	ISteamInventory* SteamInv = SteamInventory();
   339→	if (SteamInv)
   340→	{
   341→		SteamItemInstanceID_t CoinInstanceId = CachedCoinInstanceId;
   342→		if (CoinInstanceId == k_SteamItemInstanceIDInvalid)
   343→		{
   344→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Coin 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   345→			return false;
   346→		}
   347→
   348→		// 기존 핸들 정리
   349→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   350→		{
   351→			SteamInv->DestroyResult(ExchangeResultHandle);
   352→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   353→		}
   354→
   355→		// ExchangeItems: Coin 소비 → 배치 오브젝트 아이템 획득
   356→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(Def->SteamItemDefId);
   357→		uint32 OutputQuantity = 1;
   358→		uint32 InputQuantity = static_cast<uint32>(Def->CoinPrice);
   359→
   360→		bool bExchangeResult = SteamInv->ExchangeItems(
   361→			&ExchangeResultHandle,
   362→			&OutputItemDef, &OutputQuantity, 1,
   363→			&CoinInstanceId, &InputQuantity, 1
   364→		);
   365→
   366→		if (bExchangeResult)
   367→		{
   368→			bExchangePending = true;
   369→			bPendingIsPlacement = true;
   370→			PendingExchangeItemId = ObjectId;
   371→			StartExchangePolling();
   372→
   373→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공 (배치): %s (CoinInstanceId=%llu, Price=%d)"),
   374→				*ObjectId.ToString(), CoinInstanceId, Def->CoinPrice);
   375→			return true;
   376→		}
   377→		else
   378→		{
   379→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패 (배치): %s"), *ObjectId.ToString());
   380→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   381→			return false;
   382→		}
   383→	}
   384→#endif
   385→
   386→	// 비Steam 폴백: 로컬 잔액 차감 + 로컬 소유 수량 증가
   387→	SetBalance(ECurrencyType::Coin, CurrentBalance - Def->CoinPrice);
   388→
   389→	// GConfig에 소유 수량 기록
   390→	static const FString PlacementInventorySection = TEXT("PlacementInventory");
   391→	int32 CurrentOwned = 0;
   392→	GConfig->GetInt(*PlacementInventorySection, *ObjectId.ToString(), CurrentOwned, GGameUserSettingsIni);
   393→	GConfig->SetInt(*PlacementInventorySection, *ObjectId.ToString(), CurrentOwned + 1, GGameUserSettingsIni);
   394→	GConfig->Flush(false, GGameUserSettingsIni);
   395→
   396→	// CosmeticSubsystem의 AllItemQuantities도 갱신 (비Steam)
   397→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   398→	if (CosmeticSub)
   399→	{
   400→		CosmeticSub->AllItemQuantities.FindOrAdd(Def->SteamItemDefId) += 1;
   401→	}
   402→
   403→	OnPlacementPurchaseComplete.Broadcast(ObjectId, true);
   404→
   405→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 배치 오브젝트 구매 완료: %s (%d Coin 차감)"),
   406→		*ObjectId.ToString(), Def->CoinPrice);
   407→
   408→	return true;
   409→}
