   455→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   456→{
   457→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   458→	if (!Settings)
   459→	{
   460→		return;
   461→	}
   462→
   463→#if WITH_STEAM
   464→	ISteamInventory* SteamInv = SteamInventory();
   465→	if (SteamInv)
   466→	{
   467→		// CosmeticSubsystem의 캐시에서 잔액 및 인스턴스 ID 읽기
   468→		// (ParseInventoryResult()에서 이미 업데이트됨 — 중복 GetAllItems() 비동기 호출 제거)
   469→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   470→		if (CosmeticSub)
   471→		{
   472→			int32 NewCoinBalance = 0;
   473→			int32 NewGemBalance = 0;
   474→
   475→			const int32* CoinQty = CosmeticSub->AllItemQuantities.Find(Settings->CoinSteamItemDefId);
   476→			if (CoinQty)
   477→			{
   478→				NewCoinBalance = *CoinQty;
   479→			}
   480→
   481→			const int32* GemQty = CosmeticSub->AllItemQuantities.Find(Settings->GemSteamItemDefId);
   482→			if (GemQty)
   483→			{
   484→				NewGemBalance = *GemQty;
   485→			}
   486→
   487→			// 인스턴스 ID 캐시 갱신
   488→			const uint64* CoinInstId = CosmeticSub->AllItemInstanceIds.Find(Settings->CoinSteamItemDefId);
   489→			CachedCoinInstanceId = CoinInstId ? static_cast<SteamItemInstanceID_t>(*CoinInstId) : k_SteamItemInstanceIDInvalid;
   490→
   491→			const uint64* GemInstId = CosmeticSub->AllItemInstanceIds.Find(Settings->GemSteamItemDefId);
   492→			CachedGemInstanceId = GemInstId ? static_cast<SteamItemInstanceID_t>(*GemInstId) : k_SteamItemInstanceIDInvalid;
   493→
   494→			// 잔액 갱신
   495→			if (NewCoinBalance != CoinBalance)
   496→			{
   497→				SetBalance(ECurrencyType::Coin, NewCoinBalance);
   498→			}
   499→			if (NewGemBalance != GemBalance)
   500→			{
   501→				SetBalance(ECurrencyType::Gem, NewGemBalance);
   502→			}
   503→
   504→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d (InstanceId=%llu), Gem=%d (InstanceId=%llu)"),
   505→				CoinBalance, CachedCoinInstanceId, GemBalance, CachedGemInstanceId);
   506→			return;
   507→		}
   508→	}
   509→#endif
   510→
   511→	// 비Steam: 로컬 값 유지
   512→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
