   597→void UWjWorldCurrencySubsystem::DebugConsumeAllSteamItems()
   598→{
   599→#if WITH_STEAM
   600→	ISteamInventory* SteamInv = SteamInventory();
   601→	if (!SteamInv)
   602→	{
   603→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam Inventory API 없음"));
   604→		return;
   605→	}
   606→
   607→	SteamInventoryResult_t AllItemsHandle = k_SteamInventoryResultInvalid;
   608→	if (!SteamInv->GetAllItems(&AllItemsHandle))
   609→	{
   610→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 실패"));
   611→		return;
   612→	}
   613→
   614→	EResult Status = SteamInv->GetResultStatus(AllItemsHandle);
   615→	if (Status != k_EResultOK)
   616→	{
   617→		SteamInv->DestroyResult(AllItemsHandle);
   618→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 상태 실패 (%d)"), static_cast<int32>(Status));
   619→		return;
   620→	}
   621→
   622→	uint32 ItemCount = 0;
   623→	if (!SteamInv->GetResultItems(AllItemsHandle, nullptr, &ItemCount) || ItemCount == 0)
   624→	{
   625→		SteamInv->DestroyResult(AllItemsHandle);
   626→		UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: 인벤토리가 이미 비어있음"));
   627→		return;
   628→	}
   629→
   630→	TArray<SteamItemDetails_t> Items;
   631→	Items.SetNum(ItemCount);
   632→	SteamInv->GetResultItems(AllItemsHandle, Items.GetData(), &ItemCount);
   633→	SteamInv->DestroyResult(AllItemsHandle);
   634→
   635→	int32 ConsumedCount = 0;
   636→	for (const SteamItemDetails_t& Detail : Items)
   637→	{
   638→		if (Detail.m_unQuantity == 0)
   639→		{
   640→			continue;
   641→		}
   642→
   643→		SteamInventoryResult_t ConsumeHandle = k_SteamInventoryResultInvalid;
   644→		if (SteamInv->ConsumeItem(&ConsumeHandle, Detail.m_itemId, Detail.m_unQuantity))
   645→		{
   646→			UE_LOG(LogWjWorldCurrency, Log, TEXT("  소비: DefId=%d, Quantity=%d, InstanceId=%llu"),
   647→				Detail.m_iDefinition, Detail.m_unQuantity, Detail.m_itemId);
   648→			SteamInv->DestroyResult(ConsumeHandle);
   649→			++ConsumedCount;
   650→		}
   651→	}
   652→
   653→	// 캐시 초기화
   654→	CachedCoinInstanceId = k_SteamItemInstanceIDInvalid;
   655→	CachedGemInstanceId = k_SteamItemInstanceIDInvalid;
   656→
   657→	// 인벤토리 갱신
   658→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   659→	if (CosmeticSub)
   660→	{
   661→		CosmeticSub->RequestInventoryRefresh();
   662→	}
   663→
   664→	UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: %d/%d 아이템 소비 완료"), ConsumedCount, ItemCount);
   665→#else
   666→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam 환경에서만 사용 가능"));
   667→#endif
   668→}
