   675→void UWjWorldCurrencySubsystem::PollExchangeResult()
   676→{
   677→#if WITH_STEAM
   678→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   679→	{
   680→		StopExchangePolling();
   681→		return;
   682→	}
   683→
   684→	ISteamInventory* SteamInv = SteamInventory();
   685→	if (!SteamInv)
   686→	{
   687→		StopExchangePolling();
   688→		bExchangePending = false;
   689→		if (bPendingIsPlacement)
   690→		{
   691→			OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   692→		}
   693→		else
   694→		{
   695→			OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   696→		}
   697→		bPendingIsPlacement = false;
   698→		PendingExchangeItemId = NAME_None;
   699→		return;
   700→	}
   701→
   702→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   703→	if (Status == k_EResultPending)
   704→	{
   705→		return;
   706→	}
   707→
   708→	bool bSuccess = (Status == k_EResultOK);
   709→	if (bSuccess)
   710→	{
   711→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   712→
   713→		// 인벤토리 갱신
   714→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   715→		if (CosmeticSub)
   716→		{
   717→			CosmeticSub->RequestInventoryRefresh();
   718→		}
   719→	}
   720→	else
   721→	{
   722→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   723→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   724→	}
   725→
   726→	SteamInv->DestroyResult(ExchangeResultHandle);
   727→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   728→
   729→	bExchangePending = false;
   730→
   731→	// 배치 vs 코스메틱 분기
   732→	if (bPendingIsPlacement)
   733→	{
   734→		OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   735→	}
   736→	else
   737→	{
   738→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   739→	}
   740→	bPendingIsPlacement = false;
   741→	PendingExchangeItemId = NAME_None;
   742→
   743→	StopExchangePolling();
   744→#else
   745→	StopExchangePolling();
   746→#endif
   747→}
