   775→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   776→{
   777→#if WITH_STEAM
   778→	if (!bGemPurchasePending)
   779→	{
   780→		StopGemPurchasePolling();
   781→		return;
   782→	}
   783→
   784→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   785→	// 인벤토리 변경을 감지하여 완료 판단
   786→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   787→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   788→
   789→	// 간단한 타임아웃 처리 (300초)
   790→	UWorld* World = GetWorld();
   791→	if (World)
   792→	{
   793→		if (GemPurchaseStartTime == 0.0f)
   794→		{
   795→			GemPurchaseStartTime = World->GetTimeSeconds();
   796→		}
   797→
   798→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   799→		if (ElapsedTime > 300.0f)
   800→		{
   801→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   802→			bGemPurchasePending = false;
   803→			GemPurchaseStartTime = 0.0f;
   804→			StopGemPurchasePolling();
   805→		}
   806→	}
   807→#else
   808→	StopGemPurchasePolling();
   809→#endif
   810→}
