   861→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   862→{
   863→	NewAmount = FMath::Max(0, NewAmount);
   864→
   865→	switch (Type)
   866→	{
   867→	case ECurrencyType::Coin:
   868→		if (CoinBalance != NewAmount)
   869→		{
   870→			CoinBalance = NewAmount;
   871→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   872→		}
   873→		break;
   874→	case ECurrencyType::Gem:
   875→		if (GemBalance != NewAmount)
   876→		{
   877→			GemBalance = NewAmount;
   878→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   879→		}
   880→		break;
   881→	}
   882→}
