    96→void UPlacementHUDWidgetBase::PopulateCatalog(UWjWorldPlaceableObjectDataAsset* Catalog)
    97→{
    98→	if (!CatalogScrollBox || !Catalog)
    99→	{
   100→		return;
   101→	}
   102→
   103→	CatalogScrollBox->ClearChildren();
   104→	ButtonToObjectIdMap.Empty();
   105→	BuyButtonToObjectIdMap.Empty();
   106→
   107→	// 로비 컨텍스트일 때만 소유권/가격 정보 표시
   108→	const bool bIsLobby = (GetCurrentContext() == EPlacementContext::Lobby);
   109→	UWjWorldCosmeticSubsystem* CosmeticSub = nullptr;
   110→	int32 CoinBalance = 0;
   111→	int32 TotalPlacedCount = 0;
   112→	int32 MaxTotalPlaced = 0;
   113→
   114→	if (bIsLobby)
   115→	{
   116→		UGameInstance* GI = GetGameInstance();
   117→		if (GI)
   118→		{
   119→			CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   120→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   121→			if (CurrencySub)
   122→			{
   123→				CoinBalance = CurrencySub->GetBalance(ECurrencyType::Coin);
   124→			}
   125→		}
   126→
   127→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   128→		if (Settings)
   129→		{
   130→			MaxTotalPlaced = Settings->MaxTotalLobbyPlacedObjects;
   131→		}
   132→
   133→		if (PlacementComponent)
   134→		{
   135→			IWjWorldPlacementDataProvider* DataProvider = PlacementComponent->GetPlacementDataProvider();
   136→			if (DataProvider)
   137→			{
   138→				TotalPlacedCount = DataProvider->GetPlacedObjects().Num();
   139→			}
   140→		}
   141→	}
   142→
   143→	const bool bTotalLimitReached = (MaxTotalPlaced > 0 && TotalPlacedCount >= MaxTotalPlaced);
   144→
   145→	for (const FPlaceableObjectDefinition& Def : Catalog->Objects)
   146→	{
   147→		const bool bIsPaidItem = (bIsLobby && Def.CoinPrice > 0 && Def.SteamItemDefId > 0);
   148→		int32 OwnedQty = (bIsPaidItem && CosmeticSub) ? CosmeticSub->GetItemQuantityByDefId(Def.SteamItemDefId) : 0;
   149→		const bool bOwned = (!bIsPaidItem || OwnedQty > 0);
   150→
   151→		// ---- 행 컨테이너 (HorizontalBox) ----
   152→		UHorizontalBox* Row = NewObject<UHorizontalBox>(this);
   153→
   154→		// ---- 아이템 선택 버튼 ----
   155→		UButton* ItemButton = NewObject<UButton>(this);
   156→		UTextBlock* ItemText = NewObject<UTextBlock>(this);
   157→
   158→		FString DisplayStr = Def.DisplayName.IsEmpty() ? Def.ObjectId.ToString() : Def.DisplayName.ToString();
   159→
   160→		// 배치 수량 표시
   161→		if (bIsLobby && PlacementComponent)
   162→		{
   163→			int32 PlacedCount = PlacementComponent->CountPlacedObjectsByType(Def.ObjectId);
   164→			if (bIsPaidItem && Def.MaxPlacementCount > 0)
   165→			{
   166→				// 유료 아이템: 구매 수량(OwnedQty)이 설치 상한
   167→				DisplayStr += FString::Printf(TEXT("  [%d/%d]"), PlacedCount, OwnedQty);
   168→			}
   169→			else if (Def.MaxPlacementCount > 0)
   170→			{
   171→				// 무료 아이템: MaxPlacementCount가 상한
   172→				DisplayStr += FString::Printf(TEXT("  [%d/%d]"), PlacedCount, Def.MaxPlacementCount);
   173→			}
   174→		}
   175→
   176→		ItemText->SetText(FText::FromString(DisplayStr));
   177→
   178→		FSlateFontInfo FontInfo = ItemText->GetFont();
   179→		FontInfo.Size = 14;
   180→		ItemText->SetFont(FontInfo);
   181→
   182→		// 미소유 아이템: 회색 처리
   183→		if (bIsPaidItem && !bOwned)
   184→		{
   185→			ItemText->SetColorAndOpacity(FSlateColor(FLinearColor(0.5f, 0.5f, 0.5f)));
   186→		}
   187→
   188→		ItemButton->AddChild(ItemText);
   189→		Row->AddChild(ItemButton);
   190→
   191→		// 아이템 버튼 Fill (나머지 공간 차지)
   192→		if (UHorizontalBoxSlot* ItemSlot = Cast<UHorizontalBoxSlot>(ItemButton->Slot))
   193→		{
   194→			ItemSlot->SetSize(FSlateChildSize(ESlateSizeRule::Fill));
   195→		}
   196→
   197→		ButtonToObjectIdMap.Add(ItemButton, Def.ObjectId);
   198→		ItemButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnCatalogButtonClicked);
   199→
   200→		// ---- 구매 버튼 (추가 구매 가능한 유료 아이템) ----
   201→		// 유료 + 상한: 소유 수 < 상한이면 추가 구매 가능
   202→		// 유료 + 무상한(0): 미소유일 때만 1회 구매 (기존 호환)
   203→		const bool bCanBuyMore = bIsPaidItem
   204→			&& (Def.MaxPlacementCount > 0 ? OwnedQty < Def.MaxPlacementCount : !bOwned);
   205→		if (bCanBuyMore)
   206→		{
   207→			UButton* BuyButton = NewObject<UButton>(this);
   208→			UTextBlock* BuyText = NewObject<UTextBlock>(this);
   209→
   210→			BuyText->SetText(FText::FromString(FString::Printf(TEXT("%d Coin"), Def.CoinPrice)));
   211→
   212→			FSlateFontInfo BuyFont = BuyText->GetFont();
   213→			BuyFont.Size = 12;
   214→			BuyText->SetFont(BuyFont);
   215→
   216→			BuyButton->AddChild(BuyText);
   217→			Row->AddChild(BuyButton);
   218→
   219→			// 구매 가능 여부: 재화 충분 + 전체 상한 미달
   220→			bool bCanBuy = (CoinBalance >= Def.CoinPrice) && !bTotalLimitReached;
   221→
   222→			BuyButton->SetIsEnabled(bCanBuy);
   223→
   224→			BuyButtonToObjectIdMap.Add(BuyButton, Def.ObjectId);
   225→			BuyButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnBuyButtonClicked);
   226→		}
   227→
   228→		CatalogScrollBox->AddChild(Row);
   229→	}
   230→
   231→	UpdateTotalPlacementCountText();
   232→
   233→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Catalog populated with %d items"), Catalog->Objects.Num());
   234→}
