   442→void UPlacementHUDWidgetBase::UpdateTotalPlacementCountText()
   443→{
   444→	if (!TotalPlacementCountText || !PlacementComponent)
   445→	{
   446→		return;
   447→	}
   448→
   449→	if (GetCurrentContext() != EPlacementContext::Lobby)
   450→	{
   451→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Collapsed);
   452→		return;
   453→	}
   454→
   455→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   456→	IWjWorldPlacementDataProvider* DataProvider = PlacementComponent->GetPlacementDataProvider();
   457→	if (!Settings || !DataProvider)
   458→	{
   459→		return;
   460→	}
   461→
   462→	int32 CurrentCount = DataProvider->GetPlacedObjects().Num();
   463→	int32 MaxCount = Settings->MaxTotalLobbyPlacedObjects;
   464→
   465→	if (MaxCount > 0)
   466→	{
   467→		TotalPlacementCountText->SetText(FText::FromString(FString::Printf(TEXT("%d/%d"), CurrentCount, MaxCount)));
   468→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Visible);
   469→	}
   470→	else
   471→	{
   472→		TotalPlacementCountText->SetText(FText::FromString(FString::Printf(TEXT("%d"), CurrentCount)));
   473→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Visible);
   474→	}
   475→}
