   121→	{
   122→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: No catalog set"));
   123→		return;
   124→	}
   125→
   126→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
   127→	if (!Def)
   128→	{
   129→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: ObjectId=%s not found in catalog"), *ObjectId.ToString());
   130→		return;
   131→	}
   132→
   133→	// 로비 컨텍스트 + 유료 오브젝트: 소유권 체크
   134→	if (CurrentContext == EPlacementContext::Lobby && Def->CoinPrice > 0 && Def->SteamItemDefId > 0)
   135→	{
   136→		UGameInstance* GI = GetWorld() ? GetWorld()->GetGameInstance() : nullptr;
   137→		UWjWorldCosmeticSubsystem* CosmeticSub = GI ? GI->GetSubsystem<UWjWorldCosmeticSubsystem>() : nullptr;
   138→		if (CosmeticSub)
   139→		{
   140→			int32 OwnedQty = CosmeticSub->GetItemQuantityByDefId(Def->SteamItemDefId);
