   243→void AWjWorldTreasureChestActor::OnInteract()
   244→{
   245→	if (!bPlayerInRange || !InteractingPlayer)
   246→	{
   247→		return;
   248→	}
   249→
   250→	// 로컬 쿨타임 확인 (UI용, Steam에서는 서버도 이중 검증)
   251→	if (IsOnCooldown())
   252→	{
