   278→bool AWjWorldTreasureChestActor::TryGrantReward()
   279→{
   280→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   281→	if (!Settings)
   282→	{
   283→		return false;
   284→	}
   285→
   286→#if WITH_STEAM
   287→	ISteamInventory* SteamInv = SteamInventory();
   288→	if (SteamInv)
   289→	{
   290→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   291→		int32 GeneratorDefId = Settings->TreasureChestGeneratorStartDefId + ChestIndex;
   292→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   293→
   294→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   295→		{
   296→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 요청 성공 (DefId: %d)"),
   297→				ChestIndex, GeneratorDefId);
   298→			SteamInv->DestroyResult(ResultHandle);
   299→
   300→			// Steam 서버 반영 대기 후 인벤토리 갱신 (즉시 호출 시 이전 잔액 반환)
   301→			FTimerHandle TimerHandle;
   302→			GetWorldTimerManager().SetTimer(TimerHandle, [WeakThis = TWeakObjectPtr<AWjWorldTreasureChestActor>(this)]()
   303→			{
   304→				if (AWjWorldTreasureChestActor* Self = WeakThis.Get())
   305→				{
   306→					UGameInstance* GI = Self->GetGameInstance();
   307→					if (GI)
   308→					{
   309→						UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   310→						if (CosmeticSub)
   311→						{
   312→							CosmeticSub->RequestInventoryRefresh();
   313→						}
   314→					}
   315→				}
   316→			}, 1.5f, false);
   317→
   318→			return true;
   319→		}
   320→		else
   321→		{
   322→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 호출 실패 (DefId: %d)"),
   323→				ChestIndex, GeneratorDefId);
   324→			return false;
   325→		}
   326→	}
   327→#endif
   328→
   329→	// 비Steam 폴백: 로컬 재화 부여
   330→	int32 RewardAmount = Settings->TreasureChestCoinReward;
   331→	UGameInstance* GI = GetGameInstance();
   332→	if (GI)
   333→	{
   334→		UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   335→		if (CurrencySub)
   336→		{
   337→			CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   338→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 보상 %d Coin 지급"), RewardAmount);
   339→		}
   340→	}
   341→
   342→	return true;
   343→}
