   362→void AWjWorldTreasureChestActor::UpdateInteractionUI()
   363→{
   364→	if (!InteractionWidget)
   365→	{
   366→		return;
   367→	}
   368→
   369→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   370→	int32 RewardAmount = Settings ? Settings->TreasureChestCoinReward : 50;
   371→
   372→	if (IsOnCooldown())
   373→	{
   374→		FTimespan Remaining = GetRemainingCooldown();
   375→		int32 Hours = static_cast<int32>(Remaining.GetTotalHours());
   376→		int32 Minutes = Remaining.GetMinutes();
   377→		int32 Seconds = Remaining.GetSeconds();
   378→
   379→		FString CooldownText = FString::Printf(TEXT("Next open: %02d:%02d:%02d"), Hours, Minutes, Seconds);
   380→		InteractionWidget->SetInteractionText(CooldownText);
   381→	}
   382→	else
   383→	{
   384→		// 쿨타임 만료 감지 → 타이머 정지 + 비주얼 복원
   385→		GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   386→		RemoveCooldownVisual();
   387→		PlayLidClose();
   388→
   389→		FString InteractText = FString::Printf(TEXT("Open Chest (%d Coin)"), RewardAmount);
   390→		InteractionWidget->SetInteractionText(InteractText);
   391→	}
   392→}
