   410→bool AWjWorldTreasureChestActor::IsOnCooldown() const
   411→{
   412→	if (CachedLastOpenedTime.GetTicks() == 0)
   413→	{
   414→		return false;
   415→	}
   416→
   417→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   418→	float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   419→	return (FDateTime::UtcNow() - CachedLastOpenedTime).GetTotalSeconds() < CooldownSeconds;
   420→}
   421→
   422→FTimespan AWjWorldTreasureChestActor::GetRemainingCooldown() const
   423→{
   424→	if (CachedLastOpenedTime.GetTicks() == 0)
   425→	{
   426→		return FTimespan::Zero();
   427→	}
   428→
   429→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   430→	float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   431→
   432→	FDateTime CooldownEnd = CachedLastOpenedTime + FTimespan::FromSeconds(CooldownSeconds);
   433→	FTimespan Remaining = CooldownEnd - FDateTime::UtcNow();
   434→
   435→	if (Remaining.GetTotalSeconds() > 0)
   436→	{
   437→		return Remaining;
   438→	}
   439→	return FTimespan::Zero();
   440→}
