   516→void AWjWorldTreasureChestActor::ApplyCooldownVisual()
   517→{
   518→	if (!MeshComponent)
   519→	{
   520→		return;
   521→	}
   522→
   523→	int32 NumMats = MeshComponent->GetNumMaterials();
   524→	for (int32 i = 0; i < NumMats; ++i)
   525→	{
   526→		UMaterialInstanceDynamic* DMI = MeshComponent->CreateAndSetMaterialInstanceDynamic(i);
   527→		if (DMI)
   528→		{
   529→			// 어두운 회색 틴트
   530→			DMI->SetVectorParameterValue(TEXT("BaseColor"), FLinearColor(0.3f, 0.3f, 0.3f, 1.0f));
   531→			DMI->SetScalarParameterValue(TEXT("Opacity"), 0.5f);
