   539→	// 메시 재로드로 원본 머티리얼 복원
   540→	if (MeshComponent && MeshComponent->GetStaticMesh())
   541→	{
   542→		UStaticMesh* CurrentMesh = MeshComponent->GetStaticMesh();
   543→		int32 NumMats = CurrentMesh->GetStaticMaterials().Num();
   544→		for (int32 i = 0; i < NumMats; ++i)
   545→		{
   546→			MeshComponent->SetMaterial(i, CurrentMesh->GetMaterial(i));
   547→		}
   548→	}
