   105→void AWjWorldGameStatePlay::OnRep_GamePhase()
   106→{
   107→	switch (CurrentPhase)
   108→	{
   109→	case EGamePhase::Ready:
   110→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Ready"));
   111→		break;
   112→	case EGamePhase::Playing:
   113→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Started"));
   114→		break;
   115→	case EGamePhase::Finished:
   116→		// 결과 표시는 OnRep_GameResult에서 처리
   117→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Finished"));
   118→		// 게임 종료 후 ServerTravel 중 호스트 퇴장 시 마이그레이션 스킵용
   119→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   120→		{
   121→			GI->MarkGameEndTraveling();
   122→		}
   123→		break;
   124→	}
   125→
   126→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Phase changed to %d"), static_cast<int32>(CurrentPhase));
   127→}
