   129→void AWjWorldGameStatePlay::OnRep_IsGameStartCountDownReady()
   130→{
   131→	if (bIsGameStartCountDownReady)
   132→	{
   133→		UWorld* World = GetWorld();
   134→		if (!World) return;
   135→
   136→		APlayerController* PC = World->GetFirstPlayerController();
   137→		if (!PC) return;
   138→
   139→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   140→		if (!HUD) return;
   141→
   142→		// 늦게 참여한 클라이언트를 위해 남은 시간 계산
   143→		float RemainingTime = StartCountDownTime;
   144→		if (CountdownStartServerTime > 0.0)
   145→		{
   146→			double CurrentServerTime = GetServerWorldTimeSeconds();
   147→			double Elapsed = CurrentServerTime - CountdownStartServerTime;
   148→			RemainingTime = FMath::Max(0.0f, StartCountDownTime - static_cast<float>(Elapsed));
   149→		}
   150→
   151→		HUD->StartGameStartCountDown(RemainingTime);
   152→
   153→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Start Countdown Ready - %f seconds (original: %f)"), RemainingTime, StartCountDownTime);
   154→	}
   155→}
