   198→void AWjWorldGameStatePlay::OnRep_GameResult()
   199→{
   200→	if (!bGameResultReady) return;
   201→
   202→	UWorld* World = GetWorld();
   203→	if (!World) return;
   204→
   205→	APlayerController* PC = World->GetFirstPlayerController();
   206→	if (!PC) return;
   207→
   208→	AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   209→	if (!HUD) return;
   210→
   211→	FString LocalPlayerName;
   212→	if (PC->PlayerState)
   213→	{
   214→		LocalPlayerName = PC->PlayerState->GetPlayerName();
   215→	}
   216→
   217→	FString ResultText;
   218→	if (bGameHasWinner)
   219→	{
   220→		if (LocalPlayerName == WinnerPlayerName)
   221→		{
   222→			ResultText = TEXT("Victory!");
   223→		}
   224→		else
   225→		{
   226→			ResultText = FString::Printf(TEXT("%s Wins!"), *WinnerPlayerName);
   227→		}
   228→	}
   229→	else
   230→	{
   231→		ResultText = TEXT("Draw!");
   232→	}
   233→
   234→	HUD->ShowGameResultText(ResultText, 5.0f);
   235→
   236→	// 1인 플레이 시 스탯/보상 제외
   237→	const bool bShouldRecordStats = (InitialPlayerCount > 1);
   238→
   239→	// 스탯 기록 (각 클라이언트가 자신의 스탯만 기록)
   240→	// StatNamespace 기반 동적 스탯 키 생성
   241→	UWjWorldStatsSubsystem* Stats = GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   242→	if (bShouldRecordStats && Stats && PC->PlayerState && !StatNamespace.IsNone())
   243→	{
   244→		FString NS = StatNamespace.ToString();
   245→		Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_GamesPlayed"), *NS)));
   246→
   247→		if (bGameHasWinner && WinnerPlayerName == LocalPlayerName)
   248→		{
   249→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Wins"), *NS)));
   250→		}
   251→		else
   252→		{
   253→			Stats->IncrementLocalStat(FName(*FString::Printf(TEXT("%s_Losses"), *NS)));
   254→		}
   255→
   256→		Stats->StoreStats();
   257→	}
   258→	else if (!bShouldRecordStats)
   259→	{
   260→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Skipping stats/rewards for solo play (InitialPlayerCount=%d)"), InitialPlayerCount);
   261→	}
   262→
   263→	// 재화 보상 지급 (각 클라이언트가 자신의 보상 요청)
   264→	UWjWorldCurrencySubsystem* CurrencySub = GetGameInstance()->GetSubsystem<UWjWorldCurrencySubsystem>();
   265→	if (bShouldRecordStats && CurrencySub && PC->PlayerState)
   266→	{
   267→		bool bIsLocalPlayerWinner = bGameHasWinner && (WinnerPlayerName == LocalPlayerName);
   268→		CurrencySub->TriggerMatchReward(bIsLocalPlayerWinner);
   269→	}
   270→
   271→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Result - %s"), *ResultText);
   272→}
