    41→void UGA_NormalAttack::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    42→{
    43→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    44→
    45→	// EndAbility 호출용 캐시
    46→	CachedHandle = Handle;
    47→	CachedActorInfo = ActorInfo;
    48→	CachedActivationInfo = ActivationInfo;
    49→
    50→	// WallDesc 캐시
    51→	UWorld* World = GetWorld();
    52→	AWjWorldGameModePlay* GameModePlay = World ? World->GetAuthGameMode<AWjWorldGameModePlay>() : nullptr;
    53→	if (GameModePlay)
    54→	{
    55→		UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
    56→		if (GameRule)
    57→		{
    58→			CachedWallDesc = GameRule->GetWallDesc();
    59→		}
    60→	}
    61→
    62→	// GameplayCue 실행 (사운드/VFX)
    63→	if (UAbilitySystemComponent* ASC = ActorInfo->AbilitySystemComponent.Get())
    64→	{
    65→		FGameplayCueParameters CueParams;
    66→		CueParams.Location = GetAvatarActorFromActorInfo()->GetActorLocation();
    67→		ASC->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Ability_NormalAttack(), CueParams);
    68→	}
    69→
    70→	// 공격 로직 즉시 실행 (Montage와 별개로)
    71→	ExecuteAttack(ActivationInfo);
    72→
    73→	// 쿨다운 적용
    74→	ApplyCooldown(Handle, ActorInfo, ActivationInfo);
    75→
    76→	// Montage가 있으면 재생, 없으면 즉시 종료
    77→	if (AttackMontage)
    78→	{
    79→		UAbilityTask_PlayMontageAndWait* MontageTask = UAbilityTask_PlayMontageAndWait::CreatePlayMontageAndWaitProxy(
    80→			this,
    81→			NAME_None,
    82→			AttackMontage,
    83→			MontagePlayRate,
    84→			NAME_None,
    85→			true,  // bStopWhenAbilityEnds
    86→			1.0f   // AnimRootMotionTranslationScale
    87→		);
    88→
    89→		MontageTask->OnCompleted.AddDynamic(this, &UGA_NormalAttack::OnMontageCompleted);
    90→		MontageTask->OnBlendOut.AddDynamic(this, &UGA_NormalAttack::OnMontageBlendOut);
    91→		MontageTask->OnInterrupted.AddDynamic(this, &UGA_NormalAttack::OnMontageInterrupted);
    92→		MontageTask->OnCancelled.AddDynamic(this, &UGA_NormalAttack::OnMontageCancelled);
    93→		MontageTask->ReadyForActivation();
    94→	}
    95→	else
    96→	{
    97→		// Montage 없으면 즉시 종료
    98→		EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
    99→	}
   100→}
