   102→void UGA_NormalAttack::ExecuteAttack(const FGameplayAbilityActivationInfo& ActivationInfo)
   103→{
   104→	// 서버에서만 공격 처리
   105→	if (!HasAuthority(&ActivationInfo))
   106→	{
   107→		return;
   108→	}
   109→
   110→	FVector TargetLocation = CalculateTargetLocation();
   111→	FVector HalfSize = CachedWallDesc.BrickSize * 0.3f;
   112→
   113→	TArray<FOverlapResult> Overlaps;
   114→	FCollisionShape CollisionShape = FCollisionShape::MakeBox(HalfSize);
   115→
   116→	if (GetWorld()->OverlapMultiByObjectType(
   117→		Overlaps,
   118→		TargetLocation,
   119→		FQuat::Identity,
   120→		FCollisionObjectQueryParams::AllObjects,
   121→		CollisionShape))
   122→	{
   123→		for (const FOverlapResult& Overlap : Overlaps)
   124→		{
   125→			AWjWorldBrickActor* BrickActor = Cast<AWjWorldBrickActor>(Overlap.GetActor());
   126→			if (!BrickActor) continue;
   127→
   128→			UWjWorldBrickComponent* BrickComp = BrickActor->GetBrickComponent();
   129→			if (!BrickComp) continue;
   130→
   131→			const FWjWorldBrickProperties& Props = BrickComp->GetBrickProperties();
   132→
   133→			switch (Props.BrickType)
   134→			{
   135→			case EWjWorldBrickType::Standard:
   136→				// 파괴 불가
   137→				UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_NormalAttack: Standard brick - cannot destroy"));
   138→				break;
   139→
   140→			case EWjWorldBrickType::Explosive:
   141→				// 폭발 처리
   142→				UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_NormalAttack: Explosive brick - HandleWallCollision"));
   143→				BrickComp->HandleWallCollision(FVector::ZeroVector);
   144→				break;
   145→
   146→			case EWjWorldBrickType::Moving:
   147→				//UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_NormalAttack: Moving brick - destroying"));
   148→				//BrickComp->ReserveDestroyBrick(0.1f);
   149→				break;
   150→
   151→			case EWjWorldBrickType::Destructible:
   152→				// HP 기반 데미지
   153→				UE_LOG(LogWjWorldAbilities, Log, TEXT("GA_NormalAttack: Destructible brick - applying damage"));
   154→				BrickComp->ApplyDamage(1);
   155→				break;
   156→			}
   157→
   158→			// 첫 번째 벽돌만 처리
   159→			break;
   160→		}
   161→	}
   162→}
