   185→FVector UGA_NormalAttack::CalculateTargetLocation() const
   186→{
   187→	AActor* AvatarActor = GetAvatarActorFromActorInfo();
   188→	if (!AvatarActor) return FVector::ZeroVector;
   189→
   190→	FVector AvatarLocation = AvatarActor->GetActorLocation();
   191→	FRotator AvatarRotation = AvatarActor->GetActorRotation();
   192→
   193→	// Yaw 기반 4방향 스냅 (GA_SpawnBrick과 동일 패턴)
   194→	float NormalizedYaw = FRotator::NormalizeAxis(AvatarRotation.Yaw);
   195→	FVector DirectionOffset = FVector::ZeroVector;
   196→
   197→	if (NormalizedYaw >= -45.0f && NormalizedYaw < 45.0f)
   198→	{
   199→		DirectionOffset.X = CachedWallDesc.BrickSize.X;
   200→	}
   201→	else if (NormalizedYaw >= 45.0f && NormalizedYaw < 135.0f)
   202→	{
   203→		DirectionOffset.Y = CachedWallDesc.BrickSize.Y;
   204→	}
   205→	else if (NormalizedYaw >= -135.0f && NormalizedYaw < -45.0f)
   206→	{
   207→		DirectionOffset.Y = -CachedWallDesc.BrickSize.Y;
   208→	}
   209→	else
   210→	{
   211→		DirectionOffset.X = -CachedWallDesc.BrickSize.X;
   212→	}
   213→
   214→	FVector TargetPosition = AvatarLocation + DirectionOffset;
   215→
   216→	// 그리드에 스냅
   217→	FIntPoint GridIndex = UWjWorldBrickSpawner::CalculateBrickGridIndex(
   218→		TargetPosition,
   219→		CachedWallDesc.ColumnNum,
   220→		CachedWallDesc.RowNum,
   221→		CachedWallDesc.CenterOffset,
   222→		CachedWallDesc.BrickSize
   223→	);
   224→
   225→	return UWjWorldBrickSpawner::CalculateBrickPosition(
   226→		GridIndex.X,
   227→		GridIndex.Y,
   228→		CachedWallDesc.ColumnNum,
   229→		CachedWallDesc.RowNum,
   230→		CachedWallDesc.CenterOffset,
   231→		CachedWallDesc.BrickSize
   232→	);
   233→}
