    19→	NetExecutionPolicy = EGameplayAbilityNetExecutionPolicy::ServerInitiated;
    20→
    21→	FGameplayTagContainer AssetTags;
    22→	AssetTags.AddTag(WjWorldGameplayTag::Ability_Push());
    23→	SetAssetTags(AssetTags);
    24→
    25→	// SpawnBrickPreview 또는 LiftBrickCarry 상태에서는 활성화 불가
    26→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_SpawnBrickPreview());
    27→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_LiftBrickCarry());
    28→
    29→	// 쿨다운 설정
    30→	CooldownDuration = 1.5f;
    31→	CooldownTags.AddTag(WjWorldGameplayTag::Cooldown_Push());
    32→
    33→	// UI 메타데이터
    34→	AbilityName = NSLOCTEXT("Abilities", "Push", "밀치기");
    35→}
    36→
    37→void UGA_Push::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    38→{
    39→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    40→
    41→	// EndAbility 호출용 캐시
    42→	CachedHandle = Handle;
    43→	CachedActorInfo = ActorInfo;
    44→	CachedActivationInfo = ActivationInfo;
    45→
    46→	// GameplayCue 실행 (사운드/VFX)
    47→	if (UAbilitySystemComponent* ASC = ActorInfo->AbilitySystemComponent.Get())
    48→	{
    49→		FGameplayCueParameters CueParams;
    50→		CueParams.Location = GetAvatarActorFromActorInfo()->GetActorLocation();
    51→		ASC->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Ability_Push(), CueParams);
    52→	}
    53→
    54→	// 밀치기 로직 즉시 실행
    55→	ExecutePush(ActivationInfo);
    56→
    57→	// 쿨다운 적용
    58→	ApplyCooldown(Handle, ActorInfo, ActivationInfo);
    59→
    60→	// Montage가 있으면 재생, 없으면 즉시 종료
    61→	if (PushMontage)
    62→	{
    63→		UAbilityTask_PlayMontageAndWait* MontageTask = UAbilityTask_PlayMontageAndWait::CreatePlayMontageAndWaitProxy(
    64→			this,
    65→			NAME_None,
    66→			PushMontage,
    67→			MontagePlayRate,
    68→			NAME_None,
    69→			true,
    70→			1.0f
