    12→AJumpMapRotatingObstacleActor::AJumpMapRotatingObstacleActor()
    13→{
    14→	JumpMapObjectId = TEXT("RotatingObstacle");
    15→	PrimaryActorTick.bCanEverTick = true;
    16→
    17→	HitTrigger = CreateDefaultSubobject<UBoxComponent>(TEXT("HitTrigger"));
    18→	HitTrigger->SetupAttachment(RootComp);
    19→	HitTrigger->SetBoxExtent(FVector(200.f, 50.f, 50.f));
    20→	HitTrigger->SetCollisionProfileName(TEXT("OverlapAllDynamic"));
