    23→
    24→void AJumpMapRotatingObstacleActor::GetSerializableProperties(TMap<FString, FString>& OutProperties) const
    25→{
    26→	OutProperties.Add(TEXT("RotationSpeed"), FString::SanitizeFloat(RotationSpeed));
    27→	OutProperties.Add(TEXT("RotationAxis"), FString::Printf(TEXT("%.2f;%.2f;%.2f"), RotationAxis.Pitch, RotationAxis.Yaw, RotationAxis.Roll));
    28→	OutProperties.Add(TEXT("bKillOnHit"), bKillOnHit ? TEXT("1") : TEXT("0"));
    29→	OutProperties.Add(TEXT("KnockbackForce"), FString::SanitizeFloat(KnockbackForce));
    30→}
    31→
    32→void AJumpMapRotatingObstacleActor::ApplySerializedProperties(const TMap<FString, FString>& Properties)
    33→{
    34→	if (const FString* Value = Properties.Find(TEXT("RotationSpeed")))
    35→	{
    36→		RotationSpeed = FCString::Atof(**Value);
    37→	}
    38→	if (const FString* Value = Properties.Find(TEXT("RotationAxis")))
    39→	{
    40→		TArray<FString> Components;
    41→		Value->ParseIntoArray(Components, TEXT(";"), true);
    42→		if (Components.Num() >= 3)
    43→		{
    44→			RotationAxis = FRotator(FCString::Atof(*Components[0]), FCString::Atof(*Components[1]), FCString::Atof(*Components[2]));
    45→		}
    46→	}
    47→	if (const FString* Value = Properties.Find(TEXT("bKillOnHit")))
    48→	{
    49→		bKillOnHit = (*Value == TEXT("1"));
    50→	}
    51→	if (const FString* Value = Properties.Find(TEXT("KnockbackForce")))
    52→	{
    53→		KnockbackForce = FCString::Atof(**Value);
    54→	}
    55→}
    56→
    57→void AJumpMapRotatingObstacleActor::BeginPlay()
    58→{
    59→	Super::BeginPlay();
    60→
    61→	if (HasAuthority())
    62→	{
    63→		HitTrigger->OnComponentBeginOverlap.AddDynamic(this, &AJumpMapRotatingObstacleActor::OnHitOverlap);
    64→	}
    65→}
    66→
    67→void AJumpMapRotatingObstacleActor::Tick(float DeltaTime)
    68→{
    69→	Super::Tick(DeltaTime);
    70→
    71→	const FRotator DeltaRotation = RotationAxis * RotationSpeed * DeltaTime;
    72→	AddActorLocalRotation(DeltaRotation);
    73→}
    74→
    75→void AJumpMapRotatingObstacleActor::OnHitOverlap(UPrimitiveComponent* OverlappedComp, AActor* OtherActor,
    76→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
    77→{
    78→	if (!HasAuthority()) return;
    79→
    80→	AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(OtherActor);
    81→	if (!Character || Character->IsEliminated()) return;
    82→
    83→	if (bKillOnHit)
    84→	{
    85→		UWorld* World = GetWorld();
    86→		if (World)
    87→		{
    88→			AWjWorldGameModePlay* GameMode = Cast<AWjWorldGameModePlay>(World->GetAuthGameMode());
    89→			if (GameMode)
    90→			{
    91→				UWjWorldGameRuleJumpMap* GameRule = GameMode->GetCurrentGameRule<UWjWorldGameRuleJumpMap>();
    92→				if (GameRule)
    93→				{
    94→					GameRule->OnPlayerDied(Character);
    95→				}
    96→			}
    97→		}
    98→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapRotatingObstacle: Killed player [%s]"), *Character->GetName());
    99→	}
   100→	else
   101→	{
   102→		// 넉백 방향: 장애물 중심에서 캐릭터 방향
   103→		FVector KnockbackDir = (Character->GetActorLocation() - GetActorLocation()).GetSafeNormal();
   104→		KnockbackDir.Z = FMath::Max(KnockbackDir.Z, 0.3f); // 약간의 상향 넉백
   105→		KnockbackDir.Normalize();
   106→
   107→		Character->LaunchCharacter(KnockbackDir * KnockbackForce, true, true);
   108→		UE_LOG(LogWjWorld, Log, TEXT("JumpMapRotatingObstacle: Knocked back player [%s]"), *Character->GetName());
   109→	}
   110→}
